import type { CalendarItem } from "@/modules/client/data/portfolio/model";
import type { Locale } from "@/modules/shared/lib/i18n/locale";
import { getClientOnboardingMessages } from "../onboarding/messages";
import { getMessages } from "./messages";

export function portfolioCalendarTitle(item: Pick<CalendarItem, "sourceKind" | "titleFr" | "titleAr">, locale: Locale): string {
  if (item.sourceKind !== "DOCUMENT_EXPIRY") return locale === "ar" ? item.titleAr || item.titleFr : item.titleFr;
  // This source is generated by client_central_calendar_items, never a free-text event.
  const prefix = "Expiration document ";
  const code = item.titleFr.startsWith(prefix) ? item.titleFr.slice(prefix.length) : "";
  const types = getClientOnboardingMessages(locale).evidenceTypes;
  const label = Object.hasOwn(types, code) ? types[code as keyof typeof types] : null;
  const expiry = getMessages(locale).calendarSources.DOCUMENT_EXPIRY;
  return label ? `${expiry} · ${label}` : expiry;
}
